SELECT salariesfrance_13.ze2010_lib AS ze2010_lib,   AVG(CAST(salariesfrance_13.latitude AS double precision)) AS avg_latitude_ok,   AVG(CAST(salariesfrance_13.longitude AS double precision)) AS avg_longitude_ok,   SUM(salariesfrance_13.empsal_np1) AS sum_empsal_np1_ok FROM salariesfrance_13 WHERE (salariesfrance_13.reg_lib = 'NOUVELLE-AQUITAINE') GROUP BY salariesfrance_13.ze2010_lib;
